SELECT count(DISTINCT city)
FROM zip_code
WHERE county = 'Orange County' AND state = 'Virginia';

SELECT player_name
FROM Player
WHERE birthday LIKE '1970-10%';

SELECT
  (
    (CAST(SUM(CASE WHEN STRFTIME('%Y', Date) = '2010' THEN 1 ELSE 0 END) AS REAL) * 100) - (CAST(SUM(CASE WHEN STRFTIME('%Y', Date) = '2011' THEN 1 ELSE 0 END) AS REAL) * 100)
  ) / (
    (CAST(SUM(CASE WHEN STRFTIME('%Y', Date) = '2010' THEN 1 ELSE 0 END) AS REAL) + CAST(SUM(CASE WHEN STRFTIME('%Y', Date) = '2011' THEN 1 ELSE 0 END) AS REAL)) * 100
  )
FROM badges
WHERE
  Name = 'Student' AND STRFTIME('%Y', Date) IN ('2010', '2011');

SELECT SUM(T1.Consumption)
FROM yearmonth AS T1
WHERE T1.CustomerID = 6 AND T1.Date BETWEEN '201308' AND '201311';

SELECT
  SUM(CASE WHEN PLT < 100 THEN 1 ELSE 0 END) - SUM(CASE WHEN PLT > 400 THEN 1 ELSE 0 END)
FROM Laboratory;

SELECT MAX(Consumption)
FROM yearmonth
WHERE Date LIKE '2012%';
